const KEY='nova_suite_v1',$=id=>document.getElementById(id);
const state=(()=>{try{return JSON.parse(localStorage.getItem(KEY)||'{}')}catch{return {}}})();
state.projects=Array.isArray(state.projects)?state.projects:[];state.vault=Array.isArray(state.vault)?state.vault:[];state.snapshots=Array.isArray(state.snapshots)?state.snapshots:[];
state.permissions=Object.assign({ai:true,externalLinks:false,localFiles:true},state.permissions||{});
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{return false}};
