 $('arenaRun').onclick=async()=>{const q=$('arenaQ').value.trim();if(!q)return toast('Enter a task.');$('arenaOut').textContent='Running baseline…';const a=await askAI('Answer the task directly and concisely. Task: '+q);$('arenaOut').textContent='## Direct strategy\\n'+(a||'Failed')+'\\n\\n## Structured strategy\\nWorking…';const z=await askAI('Answer using assumptions, steps, edge cases and final result. Check your work and state uncertainty. Task: '+q);$('arenaOut').textContent='## Direct strategy\\n'+(a||'Failed')+'\\n\\n## Structured strategy\\n'+(z||'Failed')+'\\n\\nBoth runs used the same configured model/provider; this compares prompt strategies.'};
