function vaultSearch(){const q=$('vaultQuery')?.value.trim().toLowerCase()||'',el=$('vaultResults');if(!el)return;const hits=state.vault.filter(x=>!q||(x.title+' '+x.text).toLowerCase().includes(q));el.innerHTML=hits.length?hits.map(x=>'<div class="ns-card"><b>'+esc(x.title)+'</b><p class="ns-muted">'+esc(x.createdAt.slice(0,10))+' · '+x.text.length+' characters</p><div class="ns-out">'+esc(x.text.slice(0,500))+(x.text.length>500?'…':'')+'</div><button class="ns-quiet" data-del="'+x.id+'">Delete</button></div>').join(''):'<p class="ns-muted">No matching documents.</p>';el.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{state.vault=state.vault.filter(x=>x.id!==b.dataset.del);save();vaultSearch()})}
function auditCouncilCitations(value,sourceCount){const invalid=new Set();const safe=String(value||'').replace(/\[(S\d+)\]/g,(match,id)=>{const n=Number(id.slice(1));if(!Number.isInteger(n)||n<1||n>sourceCount){invalid.add(id);return '[INVALID SOURCE ID '+id+']'}return match});return invalid.size?safe+'\n\nCitation audit warning: the model referenced unavailable source ID(s) '+[...invalid].join(', ')+'. These citations are invalid and must not be relied on.':safe}
function renderCouncilText(el,value){el.replaceChildren();const text=String(value||''),re=/https:\/\/[^\s]+/g;let last=0,m;while((m=re.exec(text))){el.append(document.createTextNode(text.slice(last,m.index)));let raw=m[0],tail='';while(/[.,;:!?]+$/.test(raw)){tail=raw.slice(-1)+tail;raw=raw.slice(0,-1)}try{const u=new URL(raw);if(u.protocol!=='https:')throw Error();const a=document.createElement('a');a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';a.textContent=raw;a.style.color='var(--acc)';el.append(a)}catch{el.append(document.createTextNode(raw))}if(tail)el.append(document.createTextNode(tail));last=re.lastIndex}el.append(document.createTextNode(text.slice(last)))}
async function askAI(prompt,maxTokens=1100){if(!state.permissions.ai){toast('AI requests are disabled in Trust Shield.');return ''}try{const cfg=await fetch('/api/config',{cache:'no-store'});if(!cfg.ok)throw Error('AI service is not configured');const c=await cfg.json();const r=await fetch('/api/chat/completions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:c.model,stream:false,max_tokens:Math.max(256,Math.min(1800,Number(maxTokens)||1100)),temperature:0.1,messages:[{role:'user',content:prompt}] }),signal:AbortSignal.timeout(90000)});const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||('HTTP '+r.status));return String(j.choices?.[0]?.message?.content||'').trim()}catch(e){toast('AI request failed: '+String(e.message||e));return ''}}
window.NovaSuite=Object.freeze({open,close});
